<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useApi } from '../composable/useApi'
const api = useApi(); const filters = ref({ year: '2026', category: '', status: '' }); const rows = ref<any[]>([]); const loading = ref(false); const error = ref(''); const total = ref(0)
async function fetchReport() { loading.value = true; error.value = ''; try { const response = await api.get('/api/reports', { params: filters.value }); rows.value = response.data.data; total.value = response.data.total } catch (err: any) { error.value = err.response?.data?.message || 'Report request failed.' } finally { loading.value = false } }
onMounted(fetchReport)
</script>
<template><section><p class="eyebrow">Report Flow</p><h1>Filtered Report</h1><div class="filters panel"><label>Year<input v-model="filters.year" /></label><label>Category<select v-model="filters.category"><option value="">All</option><option>Revenue</option><option>Performance</option><option>Import</option></select></label><label>Status<select v-model="filters.status"><option value="">All</option><option>Completed</option><option>Pending</option><option>Failed</option></select></label><button @click="fetchReport">Apply Filters</button></div><p v-if="loading" class="alert">Loading report...</p><p v-if="error" class="alert error">{{ error }}</p><p class="muted">{{ total }} rows returned.</p><table><thead><tr><th>Year</th><th>Category</th><th>Status</th><th>Region</th><th>Total</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.year }}</td><td>{{ row.category }}</td><td>{{ row.status }}</td><td>{{ row.region }}</td><td>{{ row.total }}</td></tr></tbody></table><p class="muted">CSV export is available at the backend endpoint with a bearer token in API tools.</p></section></template>
